def head(l,title,desc,path,alternate):
 return f'''<!doctype html><html lang="{'pt-PT' if l=='pt' else 'en'}" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · SpeedDisc</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#f6f7f3"><link rel="icon" href="/favicon.ico"><link rel="canonical" href="https://speeddisc.danielpro.dev{path}"><link rel="alternate" hreflang="{'en' if l=='pt' else 'pt'}" href="https://speeddisc.danielpro.dev{alternate}"><meta property="og:title" content="{esc(title)} · SpeedDisc"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><link rel="stylesheet" href="/fonts/fonts.css"><link rel="stylesheet" href="/redesign.v1.css"><script>try{{let t=localStorage.getItem('sd-theme');document.documentElement.dataset.theme=t==='dark'||t==='light'?t:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}}catch(e){{}}</script></head><body>'''
